from scipy.optimize import least_squares
import warnings; warnings.filterwarnings('ignore')
E=df['eps'].values; TT=df['T'].values; S=df['sigma'].values
base=lambda p,e,t: p[0]+p[1]*np.log(t)+p[2]*t+(p[3]+p[4]*t)*(1-np.exp(-(p[5]+p[6]*t)*e**p[7]))
extras={'e2T':lambda e,t:e**2*t,'e2':lambda e,t:e**2,'eT2':lambda e,t:e*t**2,'eoverT':lambda e,t:e/t,'eT':lambda e,t:e*t,'e2T2':lambda e,t:e**2*t**2}
out=[]
for k,g in extras.items():
  for k2,h in [('eT',lambda e,t:e*t),('e',lambda e,t:e)]:
    fn=lambda p,e,t,g=g,h=h: base(p,e,t)+p[8]*g(e,t)+p[9]*h(e,t)
    best=None
    for s in range(10):
        p0=np.random.RandomState(s).randn(10)*0.5
        try:
            r=least_squares(lambda p: fn(p,E,TT)-S, p0, max_nfev=1500)
            if np.all(np.isfinite(r.fun)) and (best is None or r.cost<best.cost): best=r
        except Exception: pass
    if best is not None: out.append(f"{k}+{k2}: {np.mean(best.fun**2)/np.var(S):.3e}")
print("\n".join(out))
